import assert from "node:assert/strict";

export async function loadLessonCount(fetcher) {
  const response = await fetcher("/api/courses/html", { signal: AbortSignal.timeout(2000) });
  if (!response.ok) throw new Error("HTTP " + response.status);
  const data = await response.json();
  if (!data || data.courseId !== "html" || !Array.isArray(data.lessons)) {
    throw new TypeError("Invalid course payload");
  }
  return data.lessons.length;
}
const good = async () => Response.json({ courseId: "html", lessons: [{ id: "a" }, { id: "b" }] });
assert.equal(await loadLessonCount(good), 2);
console.log(await loadLessonCount(good));
try { await loadLessonCount(async () => new Response(null, { status: 503 })); }
catch (error) { console.log(error.message); }
try { await loadLessonCount(async () => Response.json({ courseId: "html", lessons: null })); }
catch (error) { console.log(error.message); }
assert.equal(await loadLessonCount(async () => Response.json({ courseId: "html", lessons: [] })), 0);
await assert.rejects(() => loadLessonCount(async () => { throw new Error("Offline"); }), /Offline/);
await assert.rejects(() => loadLessonCount(async () => new Response(null, { status: 503 })), /HTTP 503/);
await assert.rejects(() => loadLessonCount(async () => new Response(null, { status: 401 })), /HTTP 401/);
await assert.rejects(() => loadLessonCount(async () => Response.json({ lessons: [] })), TypeError);

